\begin{definition}[Bilinear  class $\cB(L_{xy},\mu_x,\mu_y)$]
	\label{defn:bilinear-class}
	In this special class, the problems are written as
	\begin{equation}
	\label{prob:bilinear}
	\min_x \max_y  F(x,y):=f(x) + x^\top Ay - g(y),
	\end{equation}
%	We require
where $f(x)$ and $g(y)$ are both lower semi-continuous with $f(x)$ being $\mu_x$-strongly convex and $g(y)$ being $\mu_y$-strongly convex. The coupling matrix $A$ satisfies $\|A\|_2\leq L_{xy}$.
\end{definition}
For this special model class $\cB(L_{xy},\mu_x,\mu_y)$, %subclass of problems,
we assume the availability of the following prox-operations:
\begin{equation}
\label{defn:prox-fg}
\prox_{\gamma f}(v):=\argmin_x f(x) + \frac{1}{2\gamma}\|x-v\|^2 \quad \mbox{ and } \quad\prox_{\sigma g}(u):=\argmin_y g(y) + \frac{1}{2\sigma}\|y-u\|^2.
\end{equation}


\subsection{Primal function, dual function, and the duality gap}
First, we define $\Phi(\cdot)$ to be the primal function and $\Psi(\cdot)$ to be the dual function of the saddle point problem $\min_x \max_y F(x,y)$, respectively, with the following definitions
\begin{equation}
\label{defn:primal-func}
\Phi(x):=\max_y F(x,y)\qquad\mbox{ and }\qquad\Psi(y):=\min_x F(x,y).
\end{equation}
As the maximum of a class of $\mu_x$-strongly convex function, we know $\Phi(x)$ is a $\mu_x$-strongly convex function. Similarly, $\Psi(y)$ is a $\mu_y$-strongly concave function. We define the duality gap as
$$\Delta(x,y) := \max_{y'} F(x,y')-\min_{x'} F(x',y) = \Phi(x)-\Psi(y).$$
Suppose the unique solution of this min-max problem is $(x^*,y^*)$. By the strong duality theorem, we know for any $x$ and $y$ it holds that 
$$\Phi(x)\geq\min_{x'}\Phi(x') = \Phi(x^*) =F(x^*,y^*) = \Psi(y^*) = \max_{y'}\Psi(y')\geq \Psi(y).$$
Together with the $\mu_x$-strong convexity of $\Phi$ and the $\mu_y$-strong concavity of $\Psi$, we further have 
\begin{equation}
\label{defn:primal-gap-LB}
\Delta(x,y)= \Phi(x)-\Phi(x^*) + \Psi(y^*) - \Psi(y)\geq\frac{\mu_x}{2}\|x-x^*\|^2 + \frac{\mu_y}{2}\|y-y^*\|^2.
\end{equation}

Now, suppose that $(\tilde x_k,\tilde y_k)$ is the approximate solution generated after $k$ iterations of an algorithm. Our aim %main strategy in the later discussion 
is to lower bound the distance between $(\tilde x_k,\tilde y_k)$ and $(x^*,y^*)$. By \eqref{defn:primal-gap-LB}, this would construct a lower iteration complexity bound in terms of the duality gap as well.


\begin{definition}[Proximal algorithm class]
\label{defn:Prox-AlgoClass}
In each iteration, the iterate sequence $\{(x^{k},y^{k})\}_{k=0,1,...}$ are generated so that  $(x^{k},y^{k})\in\cH_x^{k} \times \cH_y^{k}$. These subspaces are generated with $\cH_x^{0} = \mathrm{Span}\{x^0\}, \cH_y^{0} = \mathrm{Span}\{y^0\}$ and
\begin{equation}
\label{eqn:Prox-AlgoClass}\begin{cases}
\cH_x^{k+1} := \mathrm{Span}\{x^i,\prox_{\gamma_i f}(\hat{x}^i-\gamma_iA\tilde{y}^i)~\,: \forall \hat{x}^i\in\cH_x^{i},~ \tilde{y}^i\in\cH_y^i,~ 0\leq i\leq k\}\\
\cH_y^{k+1} := \mathrm{Span}\{y^i,\prox_{\sigma_i g}(\hat{y}^i+\sigma_iA^\top\tilde{x}^i): \forall \tilde{x}^i\in\cH_x^{i},~ \hat{y}^i\in\cH_y^i,~ 0\leq i\leq k\}.
\end{cases}
\end{equation}
\end{definition}
Remark that when applying the proximal oracles, it is not necessary to use the most recent iterate $x^k$ as the proximal center. Neither is it necessary to use the gradients of the coupling term (namely the $A^\top x$ and $Ay$ terms) at the current iterate. Instead, the algorithm class allows the usage of the combination of {\it any}\/ points in the historical search space. We shall also remark that the algorithm class in Definition~\ref{defn:Prox-AlgoClass} does not necessarily need to update $x$ and $y$ at the same time, because setting $x^{k+1}=x^k$ or $y^{k+1} = y^k$ also satisfies Definition \ref{defn:Prox-AlgoClass}. Thus this algorithm class also includes the methods that alternatingly update $x$ and $y$. Below is a sample algorithm in this class.


\subsection{General deterministic algorithm classes without linear span structure}
Although all the reviewed first-order methods satisfy the \emph{linear span} property in the proximal algorithm class in Definition \ref{defn:Prox-AlgoClass} and the pure first-order algorithm class in Definition \ref{defn:Pure-AlgoClass}, this does not exclude the possibility of the deriving an algorithm that does not satisfy the linear span property. Therefore, we also define the general deterministic proximal algorithm class and the general deterministic pure first-order algorithm class as follows, whose iteration complexity lower bound can be generalized from their linear span counterpart through the technique of \emph{adversary rotation}. 
\begin{definition}[General proximal algorithm class]
	\label{defn:Det-Prox-AlgoClass}
	Consider the problem \eqref{prob:bilinear} in the problem class $\cB(L_{xy},\mu_x,\mu_y)$, denote $\theta = (L_{xy},\mu_x,\mu_y)$ as the corresponding problem parameters. Let algorithm $\cA$ belong to the general  proximal algorithm class. Then $\cA$ consists of a sequence of deterministic mappings $\{(\cA_x^1, \cA_y^1,\cA_u^1,\cA_v^1),(\cA_x^2, \cA_y^2,\cA_u^2,\cA_v^2)...\}$ such that the iterate sequence $\{(x^{k},y^{k})\}_{k=0,1,...}$ and the output sequence $\{(\tilde x^{k},\tilde y^{k})\}_{k=0,1,...}$ are generated by 
	\begin{equation}
	\label{eqn:Det-Prox-AlgoClass}\begin{cases}
	(x^k,\tilde x^k) := \cA_x^k\left(\theta; x^0,Ay^0,...,x^{k-1},Ay^{k-1}; \mathbf{prox}_{\gamma_k f}(u^k) \right),\\
	(y^k,\tilde y^k) := \cA_y^k\left(\theta; y^0,A^\top x^0,...,y^{k-1},A^\top x^{k-1}; \mathbf{prox}_{\sigma_k g}(v^k) \right),
	\end{cases}
	\end{equation} 
	where $u^k = \cA^k_u(\theta; x^0,Ay^0,...,x^{k-1},Ay^{k-1})$, $v^k = \cA^k_v(\theta; y^0,A^\top x^0,...,y^{k-1},A^\top x^{k-1})$, and 
	$(x^0,y^0)$ is any given initial solution. 
\end{definition}
One remark is that the input of the proximal mapping $\mathbf{prox}_{\gamma_kf}(\cdot)$ is  constructed with other inputs to the $\cA_x^k$, i.e., there could be another deterministic mapping $\cA_u^k$ to generate a vector  $u^k = \cA^k_u(\theta; x^0,Ay^0,...,x^{k-1},Ay^{k-1})$ and then $\mathbf{prox}_{\gamma_kf}(u^k)$ is passed to the mapping $\cA_x^k$. This $\cA^k_u$ does not need to be linear. The situation for $v^k$ and $\cA^k_v$ is similar. Similar to the general proximal algorithm class, the general pure first-order algorithm class is defined as follows. 


Let us construct the following bilinearly coupled min-max saddle point problem:
\begin{equation}
\label{prob:worst-proximal}
\min_x\max_y F(x,y):=\frac{\mu_x}{2}\|x\|^2 + \frac{L_{xy}}{2}x^\top Ay - \frac{\mu_y}{2}\|y\|^2 - b^\top y
\end{equation}
where $b$ is a vector to be determined later, and the coupling matrix $A$ (hence $A^2$ and $A^4$) is defined as follows: %. Its polynomials $A^2$ and $A^4$ are also shown bellow for later reference.
\begin{equation}
\label{defn:A}
A = \begin{pmatrix}
& &    &     & 1\\
& &    &  1 & -1\\
& & 1 & -1&\\
& \udots &\udots & & \\
1& -1 & & &
\end{pmatrix}, \,\,
A^2 = \begin{pmatrix}
1   & -1 &            &               & \\
-1 & 2   & -1        &              & \\
& -1 &\ddots & \ddots & \\
&      &\ddots & 2           &-1\\
&      &              & -1         & 2
\end{pmatrix},
\,\,
A^4 = \begin{pmatrix}
2   & -3 &     1      &               &  & &\\
-3 & 6   & -4        &     1         & & & \\
1& -4 &6 & -4 &1 \\
&  \ddots     &\ddots & \ddots  &\ddots & \ddots & \\
& & 1& -4 &6 & -4 &1\\
& & & 1& -4 &6 & -4 \\
& & & & 1&-4&5
\end{pmatrix}.
\end{equation}
Note that $A^\top =A$ and $\|A\|_2 \leq 2$. Therefore \eqref{prob:worst-proximal} is an instance in the problem class $\cB(L_{xy},\mu_x,\mu_y)$. It is worth noting that the example \eqref{prob:worst-proximal} is the same as that in Proposition 2 of \cite{LowB-Quadratic}, which is a parallel work focused on pure first-order algorithm class. Here, we use the same example to elaborate the lower bound of the proximal methods over the general bilinear coupling class $\cB(L_{xy},\mu_x,\mu_y)$, as well as a warmup for the discussion of more complex problem class $\cF(L_{x},L_{y},L_{xy},\mu_x,\mu_y)$. 

Denote $e_i$ to be the $i$-th unit vector, which has $1$ at the $i$-th component and 0 elsewhere. Then by direct calculation, one can check that $A^2$ satisfies the following \emph{zero-chain property} (see Chapter 2 of  \cite{nesterov2018lectures}).



For problem \eqref{prob:worst-proximal}, the proximal operators in \eqref{eqn:Prox-AlgoClass} can be written explicitly:
\begin{eqnarray}
\label{defn:prox-closedForm-x}
\prox_{\gamma_i f}(\hat{x}_i-\gamma_iA\tilde{y}_i) & = & \argmin_x \frac{\mu_x}{2}\|x\|^2 + \frac{1}{2\gamma_i}\left\|x-(\hat{x}_i-\frac{\gamma_iL_{xy}}{2}A\tilde{y}_i)\right\|^2\\
& = & \frac{1}{1+\gamma_i\mu_x}\hat{x}_i - \frac{\gamma_iL_{xy}}{2(1+\gamma_i\mu_x)}A\tilde{y}_i\nonumber\\
& \in & \mathrm{Span}\{\hat{x}_i,A\tilde{y}_i\}.\nonumber
\end{eqnarray}
Similarly, for the $y$ block, we also have
\begin{eqnarray}
\label{defn:prox-closedForm-y}
\prox_{\sigma_i g}(\hat{y}_i+\sigma_iA^\top\tilde{x}_i)
%& = & \argmin_y \frac{\mu_y}{2}\|y\|^2 + b^Ty + \frac{1}{2\sigma_i}\left\|y-(\hat{y}_i+\frac{\sigma_iL_{xy}}{2}A^\top \tilde{x}_i)\right\|^2\\
=  \frac{\hat{y}_i-\sigma_i b}{1+\sigma_i\mu_y} +  \frac{\sigma_iL_{xy}}{2(1+\sigma_i\mu_x)}A\tilde{x}_i \in \mathrm{Span}\{\hat{y}_i,A\tilde{x}_i,b\}.
\end{eqnarray}
Let us assume the initial point to be $x^0 = y^0 = 0$ ($\cH_x^0 = \cH_y^0 = \{0\}$) without loss of generality.


Let us lower bound the dual gap, which is upper bounded by the whole duality gap. To achieve this, let us first write down the dual function of problem \eqref{prob:worst-proximal} as
\begin{equation}
\label{defn:dual-function-prox}
\Psi(y) = \min_{x} F(x,y) = -\frac{1}{2}y^\top \left(\frac{L_{xy}^2}{4\mu_x}\cdot A^2 + \mu_y\cdot I\right)y - b^\top y . 
\end{equation}
For this $\mu_y$-strongly concave dual function, we can characterize the optimal solution $y^*$ directly by its KKT condition $\nabla \Psi(y^*) = 0$. However, the exact solution $y^*$ does not have a simple and clear form, so we choose to  characterize it by an approximate solution $\hat y^*$.


Consider the bilinear problem class $\cB(L_{xy},\mu_x,\mu_y)$ and the corresponding worst case problem \eqref{prob:worst-proximal} with $F(x,y) = \frac{\mu_x}{2}\|x\|^2 + \frac{L_{xy}}{2}x^\top A y - \frac{\mu_y}{2}\|y\|^2 - b^\top y$,
where $A$ and $b$ are defined in accordance with Theorem \ref{thm:proximal}. We define the orthogonally rotated problem as 
\begin{equation}
\label{prob:rotate}
\min_x\max_y F_{U,V}(x,y) : = F(Ux,Vy) = \frac{\mu_x}{2}\|x\|^2 + \frac{L_{xy}}{2}x^\top U^\top AV y - \frac{\mu_y}{2}\|y\|^2 - b^\top Vy,
\end{equation}
where $U,V$ are two orthogonal matrices. Therefore, it is clear that $F_{U,V}\in\cB(L_{xy},\mu_x,\mu_y)$. Let $(x^*, y^*)$ be the saddle point of $F(x,y)$, then it is clear that the saddle point of $F_{U,V}(x,y)$ is $(\bar x^*,\bar y^*) = (U^\top  x^*,V^\top y^*).$ Consequently, the lower bound for the general proximal algorithm class is characterized by the following theorem. 


\section{Proof of Theorem \ref{theorem:gen-prox}}
\label{appdx:gen-prox} 
	Before proceeding the proof, let us first quote a lemma from \cite{YYXu}. 
	\begin{lemma}[Lemma 3.1, \cite{YYXu}] 
		\label{lemma:yyx} 
		Let $\cX\subsetneqq\bar{\cX}\subseteqq\R^{p}$ be two linear subspaces. Then for any $\bar x\in\R^p$, there exists an orthogonal matrix $\Gamma\in\R^{p\times p}$ s.t. $\Gamma x = x, \forall x\in\cX$ and $\Gamma \bar x\in\bar{\cX}$.
	\end{lemma}
	Note that for an orthogonal matrix $\Gamma$, if $\Gamma x = x$, then we also have $\Gamma^\top x = x$.  Now let us start our proof of Theorem \ref{theorem:gen-prox}.

