\begin{proposition}[Zero-chain property]
	\label{prop:zero-chain}
	For any vector $v\in\R^n$, if $v\in\mathrm{Span}\{e_i:i\leq k\}$ for some $1\leq k\leq n-1$,  then $A^2v\in\mathrm{Span}\{e_i:i\leq k+1\}$.
\end{proposition}

Directly substituting \eqref{defn:prox-closedForm-x} and \ref{defn:prox-closedForm-y} into Definition \eqref{defn:Prox-AlgoClass} yields
\begin{equation*}
\begin{cases}
\cH_x^1 \subseteq \mathrm{Span}\{0\}\\
\cH_y^1 \subseteq \mathrm{Span}\{b\}
\end{cases}
\quad
\begin{cases}
\cH_x^2 \subseteq \mathrm{Span}\{Ab\}\\
\cH_y^2 \subseteq \mathrm{Span}\{b\}
\end{cases}
\quad
\begin{cases}
\cH_x^3 \subseteq \mathrm{Span}\{Ab\}\\
\cH_y^3 \subseteq \mathrm{Span}\{b,A^2b\}
\end{cases}
\quad
\begin{cases}
\cH_x^4 \subseteq \mathrm{Span}\{Ab, A^3b\}\\
\cH_y^4 \subseteq \mathrm{Span}\{b,A^2b\}
\end{cases}
\ldots
\end{equation*}
We formally summarize this observation below: %in the Lemma \ref{lemma:subspace-prox}.
\begin{lemma}
	\label{lemma:subspace-prox}
	For problem \eqref{prob:worst-proximal}, for any $k \in \mathbb{N}$, if the iterates are generated so that  $(x_k,y_k)\in\cH_x^k\times\cH_y^k$, with $\cH_x^k$ and $\cH_y^k$ defined by \eqref{defn:Prox-AlgoClass}, then based on \eqref{defn:prox-closedForm-x} and \eqref{defn:prox-closedForm-y} the search subspaces satisfy
	$$\cH_x^k \subseteq \begin{cases}
	\{0\}, &  k = 1\\
	\mathrm{Span}\left\{A^{2i}(Ab): 0\leq i\leq \left\lfloor \frac{k}{2}\right\rfloor -1 \right\}, & k\geq 2
	\end{cases} \quad \mbox{ and }\quad
	\cH_y^k \subseteq \mathrm{Span}\left\{A^{2i}b: 0\leq i\leq \left\lceil \frac{k}{2}\right\rceil -1 \right\}.$$
\end{lemma}

\begin{lemma}[Approximate optimal solution]
	\label{lemma:apxsolu-proximal}
	Let us assign the value of $b$ as $b := -\frac{L_{xy}^2}{4\mu_x}e_1$. Denote $\alpha := \frac{4\mu_x\mu_y}{L_{xy}^2}$, and let $q = \half\left((2+\alpha) - \sqrt{(2+\alpha)^2 - 4}\right)\in(0,1)$
	be the smallest root of the quadratic equation $1 - (2+\alpha)q + q^2 = 0$. Then, an approximate optimal solution $\hat y^*$ can be constructed as
	\begin{equation}
	\hat y^*_{i} = \frac{q^i}{1-q} \quad\mbox{ for } \quad i = 1,2,...,n.
	\end{equation}
	The approximation error can be bounded by
	\begin{equation}
	\label{eqn:apxsolu-proximal}
	\|\hat y^* - y^*\| \leq  \frac{q^{n+1}}{\alpha(1-q)},
	\end{equation}
	where $\hat y^*_i$ is the $i$-th element of $\hat y^*$. Note that $q<1$ and the lower bound is dimension-independent, hence we are free to choose $n$ to make the approximation error arbitrarily small.
\end{lemma}

\begin{proof}
	First, let us substitute the value of $b$ into the KKT system $\nabla \Psi(y^*)=0$, by slight rearranging and scaling the terms, we get
	\begin{equation*}
	\left(A^2 + \frac{4\mu_x\mu_y}{L_{xy}^2} I\right)y^* = - \frac{4\mu_x}{L_{xy}^2}b.
	\end{equation*}
	Using the definition of $\alpha$ and $b$, the equation becomes
	$$(A^2+\alpha I)y^* = e_1.$$
	Substituting the formula of $A^2$ in \eqref{defn:A}, we expand the above equation as
	\begin{eqnarray}
	\label{defn:KKT-proximal}
	\begin{cases}
	(1+\alpha)y_1^* - y_2^* = 1\\
	-y_1^* + (2+\alpha)y_2^* - y_3^* = 0\\
	\qquad\qquad\quad\vdots\\
	-y_{n-2}^* + (2+\alpha)y_{n-1}^* - y_n^* = 0\\
	-y_{n-1}^* + (2+\alpha)y_n^* = 0.
	\end{cases}
	\end{eqnarray}
	By direct calculation, we can check that $\hat y^*$ satisfies the first $n-1$ equations of the KKT system \eqref{defn:KKT-proximal}. The last equation, however, is violated, but with a residual of size $q^{n+1}/(1-q)$.  In details,
	$$\begin{cases}
	(A^2 + \alpha\cdot I)\hat y^* = e_1 + \frac{q^{n+1}}{1-q}\cdot e_n\\
	(A^2 + \alpha\cdot I)y^* = e_1.
	\end{cases}$$
	This indicates that $\hat y^* - y^* = \frac{q^{n+1}}{1-q}\cdot(A^2 + \alpha I)^{-1} e_n$. Note that $\alpha^{-1}I\succeq (A^2 + \alpha I)^{-1}\succ 0$, we have the approximation error bounded by \eqref{eqn:apxsolu-proximal}.
\end{proof}

 Note that in Lemma \ref{lemma:apxsolu-proximal}, we have chosen  $b\propto e_1$. By the zero-chain property in Proposition \ref{prop:zero-chain} and Lemma \ref{lemma:subspace-prox},  we can verify that the subspaces $\cH_y^{2k-1}$ and $\cH_y^{2k}$ satisfy
\begin{equation}
\label{eqn:subspace-prox}
\cH_y^{2k-1}, \cH_y^{2k} \subseteq \mathrm{Span}\{b,A^2b,...,A^{2(k-1)}b\} =\mathrm{Span}\{e_1, e_2, ...,e_k\}.
\end{equation}
This implies that for both $y^{2k}$ and $y^{2k-1}$, the only possible nonzero elements are the first $k$ ones, which again implies that the lower bound of $\|y^{2k}-y^*\|^2$ and $\|y^{2k-1}-y^*\|^2$ will be similar. For simplicity, we only discuss this lower bound  for $y^{2k}$. The counterpart for $y^{2k-1}$ can be obtained in a similar way.  Therefore, we have the following estimations.


\begin{lemma}
	\label{lemma:lowerbound-distance-prox}
	Assume $k\leq \frac{n}{2}$ and $n\geq2\log_q\left(\frac{\alpha}{4\sqrt{2}}\right)$. Then
	\begin{equation}
	\label{eqn:lowB-dis-prox}
	\|y^{2k}-y^*\|^2\geq \frac{q^{2k}}{16}\|y^0-y^*\|^2
	\end{equation}
	where $y^0 = 0$ is the initial solution.
\end{lemma}

\begin{proof}
	By the subspace characterization \eqref{eqn:subspace-prox}, we have
	$$\|y^{2k}-\hat y^*\| \geq \sqrt{\sum^n_{j = k+1} (\hat y^*_j)^2} = \frac{q^{k}}{1-q}\sqrt{q^2 + q^4 + \cdots + q^{2(n-k)}}\geq \frac{q^k}{\sqrt{2}}\|\hat y^*\|= \frac{q^k}{\sqrt{2}}\|y^0-\hat y^*\|,$$
	where the last inequality is due to the fact that $q< 1$, $k\leq \frac{n}{2}$, and $y^0 = 0$.
 If we choose $n$ to be large enough, then $\hat y^*$ and $y^*$ can be made arbitrarily close to each other. Hence we can transform the above inequality to  \eqref{eqn:lowB-dis-prox}. More details of this derivation can be found in Appendix \ref{appendix-lowerbound-distance-prox}.
\end{proof}

Using Lemma \ref{lemma:lowerbound-distance-prox} and \eqref{defn:primal-gap-LB}, it is then straightforward to lower bound the duality gap by
$$\Delta(x^{2k},y^{2k})\geq q^{2k}\cdot\frac{\mu_y\|y^*-y^0\|^2}{32}.$$


\begin{theorem}
	\label{thm:proximal}
 Let the positive parameters $\mu_x,\mu_y>0$ and $L_{xy}> 0$ be given. For any integer $k$, there exists a problem instance from $\cB(L_{xy},\mu_x,\mu_y)$ of form \eqref{prob:worst-proximal}, with $n\geq \max\left\{2\log_q\left(\frac{\mu_x\mu_y}{\sqrt{2}L_{xy}^2}\right), 4k\right\}$, where $A\in\mathbb{R}^{n\times n}$ as defined in \eqref{defn:A}, and $b = -\frac{L_{xy}^2}{4\mu_x}e_1$. For such a problem instance, any approximate solution $(\tilde x^k, \tilde y^k)\in\cH_x^k\times\cH_y^k$ generated by the proximal algorithm class under the linear span assumption \eqref{eqn:Prox-AlgoClass}  satisfies
	\begin{eqnarray}
	\max_y F(\tilde x^{k},y) - \min_{x} F(x, \tilde y^k)\geq q^{k}\cdot\frac{\mu_y\|y^*-y^0\|^2}{32} \quad\mbox{ and }\quad \|\tilde y^k-y^*\|^2\geq q^{k}\cdot\frac{\|y^*-y^0\|^2}{16},
	\end{eqnarray}
	where $q = 1+\frac{2\mu_x\mu_y}{L_{xy}^2} - 2\sqrt{\left(\frac{\mu_x\mu_y}{L_{xy}^2}\right)^2 + \frac{\mu_x\mu_y}{L_{xy}^2}}$.
\end{theorem}

\begin{proposition}
	\label{remark:complexity-proximal}
	Under the same set of assumptions of Theorem \ref{thm:proximal}, if we require the duality gap to be bounded by $\epsilon$, the number of iterations needed is at least
	\begin{equation}
	\label{eqn:lowerbound-proximal-1stAlgo}
	k\geq \ln\left(\frac{\mu_y\|y^*-y^0\|^2}{32\epsilon}\right)/\ln(q^{-1}) = \Omega\left(\sqrt{\frac{L_{xy}^2}{\mu_x\mu_y}}\cdot\ln\left(\frac{1}{\epsilon}\right)\right).
	\end{equation}
\end{proposition}

For the proof of this theorem, we only need to construct the orthogonal matrices $U,V$ such that when the algorithm $\cA$ is applied to $F_{U,V}$, the subspace inclusion argument $\{(x^0,y^0),...,(x^k,y^k)\}\subseteq U^\top\cH_x^{4k-1}\times V^\top\cH_y^{4k-1}$ and $(\tilde x^k,\tilde y^k)\in U^\top\cH_x^{4k+1}\times V^\top\cH_y^{4k+1}$ holds. As a result, 
\begin{eqnarray*}
	\|\tilde y^k-V^\top  y^*\|^2 = \|V\tilde y^k- y^*\|^2\geq\min_{y\in\cH_y^{4k+1}}\|y-y^*\|^2\geq \frac{q^{4k+2}}{16}\|y^*-y^0\|^2.
\end{eqnarray*}
With this argument, the latter results follow directly from the discussion of Theorem \ref{thm:proximal}. The proof of this theorem is presented in Appendix \ref{appdx:gen-prox}.


\section{Proof of Lemma \ref{lemma:lowerbound-distance-prox}}
\label{appendix-lowerbound-distance-prox}
By the subspace characterization \eqref{eqn:subspace-prox}, we have
$$\|y^{2k}-\hat y^*\| \geq \sqrt{\sum^n_{j = k+1} (\hat y^*_j)^2} = \frac{q^{k}}{1-q}\sqrt{q^2 + q^4 + \cdots + q^{2(n-k)}}\geq \frac{q^k}{\sqrt{2}}\|\hat y^*\|= \frac{q^k}{\sqrt{2}}\|y^0-\hat y^*\|,$$
where the last inequality is due to the fact that $q\leq 1, k\leq \frac{n}{2}$ and $y^0 = 0$. Note that by Lemma \ref{lemma:apxsolu-proximal}, if we require $n\geq 2\log_q\left(\frac{\alpha}{4\sqrt{2}}\right)$, then we can guarantee that \begin{equation}
\label{eqn:err-n-proximal}
\|\hat y^* - y^*\| \leq \frac{q^{n+1}}{\alpha(1-q)}\leq  \frac{q^{\frac{n}{2}}}{\alpha}\cdot q^k\cdot\frac{q}{(1-q)} \leq \frac{1}{4}\cdot \frac{q^k}{\sqrt{2}}\|y^0-\hat y^*\|\quad\mbox{ for }\quad \forall 1\leq k\leq n/2,
\end{equation}
where the last inequality is due to $\frac{q^{\frac{n}{2}}}{\alpha}\leq\frac{1}{4\sqrt{2}}$ and $q/(1-q)\leq \|y^0-\hat y^*\|$. Therefore, we have
\begin{eqnarray}
\label{eqn:dist-lower-proximal}
\|y^{2k}-y^*\|^2 & \geq & (\|y^{2k}-\hat y^*\|-\|\hat y^*- y^*\|)^2\\
& \geq & \|y^{2k}-\hat y^*\|^2 - 2\|y^{2k}-\hat y^*\|\|\hat y^*- y^*\|\nonumber\\
& \geq & \min_t\left\{t^2 - 2\|\hat y^*- y^*\|t: t\geq \delta_k:= \frac{q^k}{\sqrt{2}}\|y^0-\hat y^*\|\right\}\nonumber\\
& = & \delta_k(\delta_k - 2\|\hat y^*- y^*\|)\nonumber\\
& \geq & \frac{1}{2}\delta_k^2 = \frac{q^{2k}}{4}\|y^0-\hat y^*\|^2, \nonumber
\end{eqnarray}
where the fourth line is due to that $d(t^2 - 2\|\hat y^*-y^*\|t)/dt = 2(t-\|\hat y^*-y^*\|)\geq0$ when $t\geq\delta_k$. Hence the quadratic function is monotonically increasing in the considered interval. In addition, we also have
$$\|y^0-y^*\| \leq \|y^0-\hat y^*\| + \|\hat y^*-y^*\|\leq \|y^0-\hat y^*\| + \frac{q^n}{\alpha}\cdot\frac{q}{1-q}\leq (1 + q^n/\alpha)\|y^0-\hat y^*\|\leq 2\|y^0-\hat y^*\|,$$
where the third inequality is due to that $\|y^0-\hat y^*\|\geq \hat y^*_1 = q/(1-q)$. For the last inequality, if $\alpha\geq 1$, then $q^n/\alpha<1$; if $\alpha\leq 1$, then  $q^n/\alpha\leq \alpha/32\leq1$ since $n\geq 2\log_q\left(\frac{\alpha}{4\sqrt{2}}\right)$. Combining the above two inequalities,  the desired bound \eqref{eqn:lowB-dis-prox} follows.
\section{Proof of Proposition \ref{remark:complexity-proximal}}
\label{appendix:r-complexity-proximal}
Here we only prove the last inequality of \eqref{eqn:lowerbound-proximal-1stAlgo}. Due to the fact that $(\ln(1+z))^{-1}\geq 1/z$ for $\forall z>0$, we know
\begin{eqnarray*}
(\ln(q^{-1}))^{-1} & = & (\ln(1 + (1-q)/q))^{-1} \geq \frac{q}{1-q}\\
& = &   \frac{1+\frac{2\mu_x\mu_y}{L_{xy}^2} - 2\sqrt{\left(\frac{\mu_x\mu_y}{L_{xy}^2}\right)^2 + \frac{\mu_x\mu_y}{L_{xy}^2}}}{2\sqrt{\left(\frac{\mu_x\mu_y}{L_{xy}^2}\right)^2 + \frac{\mu_x\mu_y}{L_{xy}^2}}-\frac{2\mu_x\mu_y}{L_{xy}^2}}\\
& = & \frac{\sqrt{\left(\frac{\mu_x\mu_y}{L_{xy}^2}\right)^2 + \frac{\mu_x\mu_y}{L_{xy}^2}}-\frac{\mu_x\mu_y}{L_{xy}^2}}{\frac{2\mu_x\mu_y}{L_{xy}^2}}\\
& = &  \half\sqrt{\frac{L_{xy}^2}{\mu_x\mu_y} + 1} - \frac{1}{2},\\
& = & \Omega\left(\sqrt{\frac{L_{xy}^2}{\mu_x\mu_y}}\right)
\end{eqnarray*}
which completes the proof.



\begin{proof}
		To prove this theorem, we only need to show
		$$\{(x^0,y^0),...,(x^k,y^k)\}\subseteq U^\top\cH_x^{4k-1}\times V^\top\cH_y^{4k-1}\qquad\mbox{and}\qquad(\tilde x^k,\tilde y^k)\in U^\top\cH_x^{4k+1}\times V^\top\cH_y^{4k+1}.$$
		We separate the proof into two parts.
		
		\textbf{Part I. There exist orthogonal matrices $\hat U$, $\hat V$ s.t. when $\cA$ is applied to the rotated instance $F_{\hat U,\hat V}$, $\{(x^0,y^0),...,(x^k,y^k)\}\subseteq \hat U^\top\cH_x^{4k-1}\times \hat V^\top\cH_y^{4k-1}.$}
	
		Let $\theta = (L_{xy},\mu_x,\mu_y)$ be the set of algorithmic parameters. To prove the result, let us construct the worst-case function $F_{U,V}$ in a recursive way. 	 \\
		\textbf{Case $k = 1$:} Let us define $U_0 = V_0 = I$. When $\cA$ is applied to the function $F_{U_0,V_0}\in\cB(L_{xy}, \mu_x, \mu_y)$, the iterate sequence is 
		$(x_{0}^0, y_{0}^0) = (0, 0)$ and 
		$$\begin{cases}
		u^1_0 = \cA_u^1(\theta; x_0^0, U_0^\top A V_0 y_0^0), \qquad (x^1_0, \tilde x^1_0) = \cA_x^1(\theta; x^0_0,  U_0^\top A V_0 y_0^0, \mathbf{prox}_{\gamma_1f}(u^1_0)),\\
		v^1_0 = \cA_v^1(\theta; y_0^0, V^\top_0 A U_0x_0^0),\qquad
		(y^1_0, \tilde y^1_0) = \cA_y^1(\theta; y^0_0, V^\top_0 A U_0x_0^0, \mathbf{prox}_{\sigma_1g}(v^1_0)).
		\end{cases}$$
		By Lemma \ref{lemma:yyx}, there exists orthogonal matrices $\Gamma_x^0$ and $\Gamma_y^0$ such that 
		$\Gamma_x^0x^1_0\in\cH_x^3 = \mathrm{Span}\{Ab\}$, $\Gamma_y^0y^1_0\in\cH_y^3=\mathrm{Span}\{b, A^2b\}$, and $\Gamma_y^0b = (\Gamma_y^0)^\top b = b.$ That is 
		\begin{equation}
		\label{thm:gen-prox-1}
		x_0^1\in U_1^\top\cH_x^3,\qquad\mbox{and}\qquad y_0^1\in V_1^\top\cH_y^3, \quad V_1 b = V_1^\top b = b,
		\end{equation}	
		where $U_1 = U_0\Gamma_x^0$ and $V_1 = V_0\Gamma_y^0$. 
	
		Now we prove that when we apply the algorithm $\cA$ to $F_{U_1,V_1}$, the generated iterates $\{(x^0_1, y^0_1), (x^1_1, y^1_1)\}$ satisfy that
		$(x^0_1, y^0_1) = (0, 0)$ and  $(x^1_1, y^1_1) = (x^1_0, y^1_0)$. That is, the first two iterates generated by $\cA$ is completely the same for $F_{U_0,V_0}$ and $F_{U_1,V_1}$. The reason is because 
		$u^1_1 = \cA_u^1(\theta; x^0_1, U_1^\top AV_1y^0_1) = \cA_u^1(\theta; 0, 0) = \cA_u^1(\theta; x^0_0, U_0^\top AV_0y^0_0)  = u^1_0$, 
		therefore 
		\begin{eqnarray*}
			(x^1_1, \tilde x^1_1) & = & \cA_x^1(\theta; x^0_1, U_1^\top A V_1 y_1^0, \mathbf{prox}_{\gamma_1f}(u^1_1)) \\
			& = & \cA_x^1(\theta; 0, 0, \mathbf{prox}_{\gamma_1f}(u^1_1)) \\
			& = & \cA_x^1(\theta; x^0_0, U_0^\top A V_0 y_0^0, \mathbf{prox}_{\gamma_1f}(u^1_0)) \\
			& = & (x^1_0, \tilde x^1_0).
		\end{eqnarray*}
		Through similar argument, we know $(y^1_1,\tilde y^1_1) = (y^1_0,\tilde y^1_0)$. Therefore, \eqref{thm:gen-prox-1} indicates that 
		\begin{equation}
		\label{thm:gen-prox-2}
		x_1^1\in U_1^\top\cH_x^3,\qquad\mbox{and}\qquad y_1^1\in V_1^\top\cH_y^3, \quad V_1 b = V_1^\top b = b\in V_1^\top\cH_y^3.
		\end{equation}
		\textbf{Case $k=2$.} For the ease of the readers to follow, we perform one extra step of discussion for $k=2$, before presenting the construction on general $k$. 
	    
		For the problem instance $F_{U_1,V_1}$, the iterates generated by $\cA$ are $(x_{1}^0, y_{1}^0) = (0, 0)$ and 
		$$\begin{cases}
		u^1_1 = \cA_u^1(\theta; x_1^0, U_1^\top A V_1 y_1^0), \qquad (x^1_1, \tilde x^1_1) = \cA_x^1(\theta; x^0_1,  U_1^\top A V_1 y_1^0, \mathbf{prox}_{\gamma_1f}(u^1_1)),\\
		v^1_1 = \cA_v^1(\theta; y_1^0, V^\top_1 A U_1x_1^0),\qquad
		(y^1_1, \tilde y^1_1) = \cA_y^1(\theta; y^0_1, V^\top_1 A U_1x_1^0, \mathbf{prox}_{\sigma_1g}(v^1_1)).\\
		\end{cases}$$
		$$\begin{cases}
		u^2_1 = \cA_u^2(\theta; x_1^0, U_1^\top A V_1 y_1^0, x_1^1, U_1^\top A V_1 y_1^1), \quad (x^2_1, \tilde x^2_1) = \cA_x^2(\theta; x^0_1,  U_1^\top A V_1 y_1^0, x_1^1, U_1^\top A V_1 y_1^1, \mathbf{prox}_{\gamma_2f}(u^2_1)),\\
		v^2_1 = \cA_v^2(\theta; y_1^0, V^\top_1 A U_1x_1^0, y_1^1, V^\top_1 A U_1x_1^1),\quad
		(y^2_1, \tilde y^2_1) = \cA_y^2(\theta; y^0_1, V^\top_1 A U_1x_1^0, y_1^1, V^\top_1 A U_1x_1^1, \mathbf{prox}_{\sigma_2g}(v^2_1)).\\
		\end{cases}$$
		Note that  $x_1^1 \in U_1^\top\cH_x^3 \subsetneqq U_1^\top\cH_x^5\subsetneqq U_1^\top\cH_x^7$ and $\{y_1^1,b\}\subsetneqq V_1^\top\cH_y^3\subsetneqq V_1^\top\cH_y^5\subsetneqq V_1^\top\cH_y^7$. Therefore, there exist orthogonal matrices $\Gamma_x^1$ and $\Gamma_y^1$ such that 
		\begin{equation}
		\label{thm:gen-prox-3}
		\begin{cases}
		\Gamma_x^1x = (\Gamma_x^1)^\top x = x, \,\,\forall x\in U_1^\top\cH_x^5,\,\,\,\, \Gamma_x^1 x_1^2\in U_1^\top\cH_x^7,\\
		\Gamma_y^1y \,= (\Gamma_y^1)^\top y = y, \,\,\,\forall y\in V_1^\top\cH_y^5,\,\,\,\, \Gamma_y^1 y_1^2\in V_1^\top\cH_y^7.
		\end{cases}
		\end{equation}
		Now, let us define 
		$$U_2 = U_1\Gamma_x^1\qquad\mbox{and}\qquad V_2 = V_1\Gamma_y^1.$$
		Now we prove that if $\cA$ is applied to $F_{U_2,V_2}$, the generated iterates $\{(x_{2}^0, y_{2}^0), (x_{2}^1, y_{2}^1), (x_{2}^2, y_{2}^2)\}$ satisfy $(x_{2}^0, y_{2}^0) = (0, 0)$, $(x_{2}^1, y_{2}^1) = (x_{1}^1, y_{1}^1)$, and  $(x_{2}^2, y_{2}^2) = (x_{1}^2, y_{1}^2)$. The argument for $(x_{2}^1, y_{2}^1) = (x_{1}^1, y_{1}^1)$ is almost the same as  that of the case $k=1$. We only provide the proof for $(x_{2}^2, y_{2}^2) = (x_{1}^2, y_{1}^2)$.
	
	Next, we need to show $u_2^2 = u_1^2$, which can be proved by arguing that all the inputs to $\cA_u^2$ are the same for both $u_2^2$ and $u_1^2$. First, it is straightforward that $x_1^0 = 0 = x^0_2, U_1^\top AV_1 y_1^0 = 0 = U_2^\top AV_2 y_2^0$. By previous argument $x_2^1 = x_1^1$.  Finally, consider the last input $U_2^\top AV_2 y_2^1$, because $y_2^1 = y_1^1\in V_1^\top\cH_y^3\subsetneqq V_1^\top\cH_y^5$, we have $\Gamma_y^1 y_2^1 = y_2^1 = y_1^1\in V_1^\top\cH_y^3.$ Then $V_2y_2^1 = V_1\Gamma_y^1y_2^1\in V_1V_1^\top\cH_y^3 = \cH_y^3.$ Therefore $U_1^\top AV_2y_2^1\in U_1^\top A\cH_y^3 = U_1^\top\cH_x^5$ and 
		$$U_2^\top AV_2y_2^1 = \Gamma_x^1U_1^\top AV_2y_2^1 = U_1^\top AV_2y_2^1 = U_1^\top AV_1\Gamma_y^1y_2^1 = U_1^\top AV_1y_1^1.$$ 
		Consequently, 
		\begin{eqnarray*}
			u_2^2  = \cA_u^2(\theta; x_2^0, U_2^\top AV_2 y_2^0, x_2^1, U_2^\top AV_2 y_2^1)
			=\cA_u^2(\theta; x_1^0, U_1^\top AV_1 y_1^0, x_1^1, U_1^\top AV_1 y_1^1)
			= u_2^1
		\end{eqnarray*}
		and 
		\begin{eqnarray*}
			(x_2^2,\tilde x_2^2)  & = & \cA_x^2(\theta; x_2^0, U_2^\top AV_2 y_2^0, x_2^1, U_2^\top AV_2 y_2^1,\mathbf{prox}_{\gamma_2f}(u^2_2))\\
			& = &\cA_x^2(\theta; x_1^0, U_1^\top AV_1 y_1^0, x_1^1, U_1^\top AV_1 y_1^1,\mathbf{prox}_{\gamma_2f}(u^2_1))\\
			& = & (x_1^2,\tilde x_1^2).
		\end{eqnarray*}
		Through a similar argument, we have $(y_2^2,\tilde y_2^2) = (y_1^2,\tilde y_1^2)$. By \eqref{thm:gen-prox-2} and \eqref{thm:gen-prox-3}, we have 
		\begin{equation}
		\label{thm:gen-prox-4}
		\{x_2^0,x_2^1,x_2^2\}\in U_2^\top\cH_x^7\qquad\mbox{and}\qquad\{b,y_2^0,y_2^1,y_2^2\}\in V_2^\top\cH_y^7.
		\end{equation}
		\textbf{Case $k$.} Suppose we already have orthogonal matrices $U_{k-1}, V_{k-1}$, such that when $\cA$ is applied to $F_{U_{k-1},V_{k-1}}$, we have
		\begin{equation}
		\label{thm:gen-prox-5}
		\{x_{k-1}^0,x_{k-1}^1,\cdots, x_{k-1}^{k-1}\}\in U_{k-1}^\top\cH_x^{4k-5}\qquad\mbox{and}\qquad\{b,y_{k-1}^0,y_{k-1}^1,\cdots,y_{k-1}^{k-1}\}\in V_{k-1}^\top\cH_y^{4k-5}.
		\end{equation}
		Again, by Lemma \ref{lemma:yyx}, there exist orthogonal matrices $\Gamma_x^{k-1}$ and $\Gamma_y^{k-1}$, such that 
		\begin{equation}
		\label{thm:gen-prox-6}
		\begin{cases}
		\Gamma_x^{k-1}x = (\Gamma_x^{k-1})^\top x = x, \,\,\forall x\in U_{k-1}^\top\cH_x^{4k-3},\,\,\,\, \Gamma_x^{k-1} x_{k-1}^{k}\in U_{k-1}^\top\cH_x^{4k-1},\\
		\Gamma_y^{k-1}y \,= (\Gamma_y^{k-1})^\top y = y, \,\,\,\forall y\in V_{k-1}^\top\cH_y^{4k-3},\,\,\,\, \Gamma_y^{k-1} y_{k-1}^k\in V_{k-1}^\top\cH_y^{4k-1}.
		\end{cases}
		\end{equation}
		Now we define that 
		$$U_k = U_{k-1}\Gamma_x^{k-1} \qquad\mbox{and}\qquad V_k = V_{k-1}\Gamma_y^{k-1}.$$
		Therefore, similar to our previous discussion, we only need to argue that when $\cA$ is applied to $F_{U_k,V_k}$, the generated iterates $\{(x_k^0,y_k^0), (x_k^1,y_k^1),\cdots,(x_k^k,y_k^k)\}$ satisfy $(x_k^i,y_k^i) = (x_{k-1}^i,y_{k-1}^i)$ for $i = 0,1,...,k$. We prove this argument by induction. First, it is straightforward that $(x_k^0,y_k^0) = (0,0) = (x_{k-1}^0,y_{k-1}^0)$. Suppose $(x_k^i,y_k^i) = (x_{k-1}^i,y_{k-1}^i)$ holds for $i = 0,1,...,j-1\leq k-1$, now we prove $(x_k^j,y_k^j) = (x_{k-1}^j,y_{k-1}^j)$, which is almost identical to the case $k=2$.
	
	For any $i\in\{0,1,...,j-1\}$, let us show $U_{k-1}^\top AV_{k-1} y_{k-1}^i = U_k^\top AV_k y_k^i$. Because $y_k^i = y_{k-1}^i\in V_{k-1}^\top\cH_y^{4k-5}\subsetneqq V_{k-1}^\top\cH_y^{4k-3}$, we have $\Gamma_y^{k-1} y_k^i = y_k^i = y_{k-1}^i\in V_{k-1}^\top\cH_y^{4k-5}.$ Then $V_ky_k^i = V_{k-1}\Gamma_y^{k-1}y_k^i\in V_{k-1}V_{k-1}^\top\cH_y^{4k-5} = \cH_y^{4k-5}.$ Therefore $U_{k-1}^\top AV_{k}y_k^i\in U_{k-1}^\top A\cH_y^{4k-5} = U_{k-1}^\top\cH_x^{4k-3}$ and 
		$$U_k^\top AV_ky_k^i = (\Gamma_x^{k-1})^\top U_{k-1}^\top AV_ky_k^i = U_{k-1}^\top AV_{k}y_k^i = U_{k-1}^\top AV_{k-1}\Gamma_y^{k-1}y_k^i = U_{k-1}^\top AV_{k-1}y_{k-1}^i,$$ 
		for $0\leq i\leq j-1$. Consequently, 
		\begin{eqnarray*}
			u_k^i  & = & \cA_u^i(\theta; x_k^0, U_k^\top AV_k y_k^0,..., x_k^{i-1}, U_k^\top AV_k y_k^{i-1})\\
			& = & \cA_u^i(\theta; x_{k-1}^0, U_{k-1}^\top AV_{k-1} y_{k-1}^0,..., x_{k-1}^{i-1}, U_{k-1}^\top AV_{k-1} y_{k-1}^{i-1})\\
			& = & u_{k-1}^i
		\end{eqnarray*}
		and 
		\begin{eqnarray*}
			(x_k^i,\tilde x_k^i)  & = & \cA_x^i(\theta; x_k^0, U_k^\top AV_k y_k^0,..., x_k^{i-1}, U_k^\top AV_k y_k^{i-1},\mathbf{prox}_{\gamma_if}(u^i_k))\\
			& = &\cA_x^2(\theta; x_{k-1}^0, U_{k-1}^\top AV_{k-1} y_{k-1}^0,..., x_{k-1}^{i-1}, U_{k-1}^\top AV_{k-1} y_{k-1}^{i-1},\mathbf{prox}_{\gamma_if}(u^i_{k-1}))\\
			& = & (x_{k-1}^i,\tilde x_{k-1}^i).
		\end{eqnarray*}
		Through a similar argument, we have $(y_k^i,\tilde y_k^i) = (y_{k-1}^i,\tilde y_{k-1}^i)$. By induction, we know $(y_k^i,\tilde y_k^i) = (y_{k-1}^i,\tilde y_{k-1}^i)$ for $i = 0,1,...,k$. Consequently, we have 
		\begin{equation}
		\label{thm:gen-prox-7}
		\{x_{k}^0,x_{k}^1,\cdots, x_{k}^{k}\}\in U_{k}^\top\cH_x^{4k-1}\qquad\mbox{and}\qquad\{b,y_{k}^0,y_{k}^1,\cdots,y_{k}^{k}\}\in V_{k}^\top\cH_y^{4k-1}.
		\end{equation}
	    By setting $\hat U = U_k$ and $\hat V = V_k$, we prove the result for Part I.\vspace{0.5cm}\\       
       	\textbf{Part II. There exist orthogonal matrices $U$, $V$ such that when $\cA$ is applied to the rotated instance $F_{U,V}$, $\{(x^0,y^0),...,(x^k,y^k)\}\subseteq U^\top\cH_x^{4k-1}\times V^\top\cH_y^{4k-1},$ and $(\tilde{x}^k,\tilde{y}^k)\in U^\top\cH_x^{4k+1}\times V^\top\cH_y^{4k+1}$}.
       
       Given the result of Part I, and let $\{(x_k^0, y_k^0),...,(x_k^k, y_k^k)\}$ and $(\tilde x_k^k, \tilde y_k^k)$ be generated by $\cA$ when applied to $F_{\hat U,\hat V} = F_{U_k,V_k}$. Therefore, by Lemma \ref{lemma:yyx}, there exist orthogonal matrices $P,Q$ such that 
       \begin{equation}
       \label{thm:gen-prox-8}
       \begin{cases}
       Px = P^\top x = x, \,\,\forall x\in U_{k}^\top\cH_x^{4k-1},\,\,\,\, P \tilde x_{k}^{k}\in U_{k}^\top\cH_x^{4k+1},\\
       Qy \,=Q^\top y = y, \,\,\forall y\in V_{k}^\top\cH_y^{4k-1},\,\,\,\, Q\tilde y_{k}^k\in V_{k}^\top\cH_y^{4k+1}.
       \end{cases}
       \end{equation}
       Define $U = U_kP$, and $V = V_kQ$. Let $\{(x^0,y^0),...,(x^k,y^k)\}$ and the output $(\tilde x^k,\tilde y^k)$ be generated by $\cA$ when applied to $F_{{U,V}}$. Then following the same line of argument of Case $k$, Part I, we have 
       $$(x^i,y^i) = (x^i_k,y^i_k), \,\,\mbox{for}\,\, i = 0,1,...,k\qquad\mbox{and}\qquad(\tilde x^k,\tilde y^k) = (\tilde x^k_k,\tilde y^k_k).$$
       Therefore, combining \eqref{thm:gen-prox-8}, we complete the proof of Part II.  
\end{proof}

