		\begin{eqnarray*}
			u_2^2  = \cA_u^2(\theta; x_2^0, U_2^\top AV_2 y_2^0, x_2^1, U_2^\top AV_2 y_2^1)
			=\cA_u^2(\theta; x_1^0, U_1^\top AV_1 y_1^0, x_1^1, U_1^\top AV_1 y_1^1)
			= u_2^1
		\end{eqnarray*}
		and 
		\begin{eqnarray*}
			(x_2^2,\tilde x_2^2)  & = & \cA_x^2(\theta; x_2^0, U_2^\top AV_2 y_2^0, x_2^1, U_2^\top AV_2 y_2^1,\mathbf{prox}_{\gamma_2f}(u^2_2))\\
			& = &\cA_x^2(\theta; x_1^0, U_1^\top AV_1 y_1^0, x_1^1, U_1^\top AV_1 y_1^1,\mathbf{prox}_{\gamma_2f}(u^2_1))\\
			& = & (x_1^2,\tilde x_1^2).
		\end{eqnarray*}
		Through a similar argument, we have $(y_2^2,\tilde y_2^2) = (y_1^2,\tilde y_1^2)$. By \eqref{thm:gen-prox-2} and \eqref{thm:gen-prox-3}, we have 
		\begin{equation}
		\label{thm:gen-prox-4}
		\{x_2^0,x_2^1,x_2^2\}\in U_2^\top\cH_x^7\qquad\mbox{and}\qquad\{b,y_2^0,y_2^1,y_2^2\}\in V_2^\top\cH_y^7.
		\end{equation}
		\textbf{Case $k$.} Suppose we already have orthogonal matrices $U_{k-1}, V_{k-1}$, such that when $\cA$ is applied to $F_{U_{k-1},V_{k-1}}$, we have
		\begin{equation}
		\label{thm:gen-prox-5}
		\{x_{k-1}^0,x_{k-1}^1,\cdots, x_{k-1}^{k-1}\}\in U_{k-1}^\top\cH_x^{4k-5}\qquad\mbox{and}\qquad\{b,y_{k-1}^0,y_{k-1}^1,\cdots,y_{k-1}^{k-1}\}\in V_{k-1}^\top\cH_y^{4k-5}.
		\end{equation}
		Again, by Lemma \ref{lemma:yyx}, there exist orthogonal matrices $\Gamma_x^{k-1}$ and $\Gamma_y^{k-1}$, such that 
		\begin{equation}
		\label{thm:gen-prox-6}
		\begin{cases}
		\Gamma_x^{k-1}x = (\Gamma_x^{k-1})^\top x = x, \,\,\forall x\in U_{k-1}^\top\cH_x^{4k-3},\,\,\,\, \Gamma_x^{k-1} x_{k-1}^{k}\in U_{k-1}^\top\cH_x^{4k-1},\\
		\Gamma_y^{k-1}y \,= (\Gamma_y^{k-1})^\top y = y, \,\,\,\forall y\in V_{k-1}^\top\cH_y^{4k-3},\,\,\,\, \Gamma_y^{k-1} y_{k-1}^k\in V_{k-1}^\top\cH_y^{4k-1}.
		\end{cases}
		\end{equation}
		Now we define that 
		$$U_k = U_{k-1}\Gamma_x^{k-1} \qquad\mbox{and}\qquad V_k = V_{k-1}\Gamma_y^{k-1}.$$
		Therefore, similar to our previous discussion, we only need to argue that when $\cA$ is applied to $F_{U_k,V_k}$, the generated iterates $\{(x_k^0,y_k^0), (x_k^1,y_k^1),\cdots,(x_k^k,y_k^k)\}$ satisfy $(x_k^i,y_k^i) = (x_{k-1}^i,y_{k-1}^i)$ for $i = 0,1,...,k$. We prove this argument by induction. First, it is straightforward that $(x_k^0,y_k^0) = (0,0) = (x_{k-1}^0,y_{k-1}^0)$. Suppose $(x_k^i,y_k^i) = (x_{k-1}^i,y_{k-1}^i)$ holds for $i = 0,1,...,j-1\leq k-1$, now we prove $(x_k^j,y_k^j) = (x_{k-1}^j,y_{k-1}^j)$, which is almost identical to the case $k=2$.
	
	For any $i\in\{0,1,...,j-1\}$, let us show $U_{k-1}^\top AV_{k-1} y_{k-1}^i = U_k^\top AV_k y_k^i$. Because $y_k^i = y_{k-1}^i\in V_{k-1}^\top\cH_y^{4k-5}\subsetneqq V_{k-1}^\top\cH_y^{4k-3}$, we have $\Gamma_y^{k-1} y_k^i = y_k^i = y_{k-1}^i\in V_{k-1}^\top\cH_y^{4k-5}.$ Then $V_ky_k^i = V_{k-1}\Gamma_y^{k-1}y_k^i\in V_{k-1}V_{k-1}^\top\cH_y^{4k-5} = \cH_y^{4k-5}.$ Therefore $U_{k-1}^\top AV_{k}y_k^i\in U_{k-1}^\top A\cH_y^{4k-5} = U_{k-1}^\top\cH_x^{4k-3}$ and 
		$$U_k^\top AV_ky_k^i = (\Gamma_x^{k-1})^\top U_{k-1}^\top AV_ky_k^i = U_{k-1}^\top AV_{k}y_k^i = U_{k-1}^\top AV_{k-1}\Gamma_y^{k-1}y_k^i = U_{k-1}^\top AV_{k-1}y_{k-1}^i,$$ 
		for $0\leq i\leq j-1$. Consequently, 
		\begin{eqnarray*}
			u_k^i  & = & \cA_u^i(\theta; x_k^0, U_k^\top AV_k y_k^0,..., x_k^{i-1}, U_k^\top AV_k y_k^{i-1})\\
			& = & \cA_u^i(\theta; x_{k-1}^0, U_{k-1}^\top AV_{k-1} y_{k-1}^0,..., x_{k-1}^{i-1}, U_{k-1}^\top AV_{k-1} y_{k-1}^{i-1})\\
			& = & u_{k-1}^i
		\end{eqnarray*}
		and 
		\begin{eqnarray*}
			(x_k^i,\tilde x_k^i)  & = & \cA_x^i(\theta; x_k^0, U_k^\top AV_k y_k^0,..., x_k^{i-1}, U_k^\top AV_k y_k^{i-1},\mathbf{prox}_{\gamma_if}(u^i_k))\\
			& = &\cA_x^2(\theta; x_{k-1}^0, U_{k-1}^\top AV_{k-1} y_{k-1}^0,..., x_{k-1}^{i-1}, U_{k-1}^\top AV_{k-1} y_{k-1}^{i-1},\mathbf{prox}_{\gamma_if}(u^i_{k-1}))\\
			& = & (x_{k-1}^i,\tilde x_{k-1}^i).
		\end{eqnarray*}
		Through a similar argument, we have $(y_k^i,\tilde y_k^i) = (y_{k-1}^i,\tilde y_{k-1}^i)$. By induction, we know $(y_k^i,\tilde y_k^i) = (y_{k-1}^i,\tilde y_{k-1}^i)$ for $i = 0,1,...,k$. Consequently, we have 
		\begin{equation}
		\label{thm:gen-prox-7}
		\{x_{k}^0,x_{k}^1,\cdots, x_{k}^{k}\}\in U_{k}^\top\cH_x^{4k-1}\qquad\mbox{and}\qquad\{b,y_{k}^0,y_{k}^1,\cdots,y_{k}^{k}\}\in V_{k}^\top\cH_y^{4k-1}.
		\end{equation}
	    By setting $\hat U = U_k$ and $\hat V = V_k$, we prove the result for Part I.\vspace{0.5cm}\\       
       	\textbf{Part II. There exist orthogonal matrices $U$, $V$ such that when $\cA$ is applied to the rotated instance $F_{U,V}$, $\{(x^0,y^0),...,(x^k,y^k)\}\subseteq U^\top\cH_x^{4k-1}\times V^\top\cH_y^{4k-1},$ and $(\tilde{x}^k,\tilde{y}^k)\in U^\top\cH_x^{4k+1}\times V^\top\cH_y^{4k+1}$}.
       
       Given the result of Part I, and let $\{(x_k^0, y_k^0),...,(x_k^k, y_k^k)\}$ and $(\tilde x_k^k, \tilde y_k^k)$ be generated by $\cA$ when applied to $F_{\hat U,\hat V} = F_{U_k,V_k}$. Therefore, by Lemma \ref{lemma:yyx}, there exist orthogonal matrices $P,Q$ such that 
       \begin{equation}
       \label{thm:gen-prox-8}
       \begin{cases}
       Px = P^\top x = x, \,\,\forall x\in U_{k}^\top\cH_x^{4k-1},\,\,\,\, P \tilde x_{k}^{k}\in U_{k}^\top\cH_x^{4k+1},\\
       Qy \,=Q^\top y = y, \,\,\forall y\in V_{k}^\top\cH_y^{4k-1},\,\,\,\, Q\tilde y_{k}^k\in V_{k}^\top\cH_y^{4k+1}.
       \end{cases}
       \end{equation}
       Define $U = U_kP$, and $V = V_kQ$. Let $\{(x^0,y^0),...,(x^k,y^k)\}$ and the output $(\tilde x^k,\tilde y^k)$ be generated by $\cA$ when applied to $F_{{U,V}}$. Then following the same line of argument of Case $k$, Part I, we have 
       $$(x^i,y^i) = (x^i_k,y^i_k), \,\,\mbox{for}\,\, i = 0,1,...,k\qquad\mbox{and}\qquad(\tilde x^k,\tilde y^k) = (\tilde x^k_k,\tilde y^k_k).$$
       Therefore, combining \eqref{thm:gen-prox-8}, we complete the proof of Part II.  
\end{proof}

For the proof of this theorem, we only need to construct the orthogonal matrices $U,V$ such that when the algorithm $\cA$ is applied to $F_{U,V}$, the subspace inclusion argument $\{(x^0,y^0),...,(x^k,y^k)\}\subseteq U^\top\cH_x^{4k-1}\times V^\top\cH_y^{4k-1}$ and $(\tilde x^k,\tilde y^k)\in U^\top\cH_x^{4k+1}\times V^\top\cH_y^{4k+1}$ holds. As a result, 
\begin{eqnarray*}
	\|\tilde y^k-V^\top  y^*\|^2 = \|V\tilde y^k- y^*\|^2\geq\min_{y\in\cH_y^{4k+1}}\|y-y^*\|^2\geq \frac{q^{4k+2}}{16}\|y^*-y^0\|^2.
\end{eqnarray*}
With this argument, the latter results follow directly from the discussion of Theorem \ref{thm:proximal}. The proof of this theorem is presented in Appendix \ref{appdx:gen-prox}.

\begin{proof}
		To prove this theorem, we only need to show
		$$\{(x^0,y^0),...,(x^k,y^k)\}\subseteq U^\top\cH_x^{4k-1}\times V^\top\cH_y^{4k-1}\qquad\mbox{and}\qquad(\tilde x^k,\tilde y^k)\in U^\top\cH_x^{4k+1}\times V^\top\cH_y^{4k+1}.$$
		We separate the proof into two parts.
		
		\textbf{Part I. There exist orthogonal matrices $\hat U$, $\hat V$ s.t. when $\cA$ is applied to the rotated instance $F_{\hat U,\hat V}$, $\{(x^0,y^0),...,(x^k,y^k)\}\subseteq \hat U^\top\cH_x^{4k-1}\times \hat V^\top\cH_y^{4k-1}.$}
	
		Let $\theta = (L_{xy},\mu_x,\mu_y)$ be the set of algorithmic parameters. To prove the result, let us construct the worst-case function $F_{U,V}$ in a recursive way. 	 \\

By Lemma \ref{lemma:yyx}, there exists orthogonal matrices $\Gamma_x^0$ and $\Gamma_y^0$ such that 
$\Gamma_x^0x^1_0\in\cH_x^3 = \mathrm{Span}\{Ab\}$, $\Gamma_y^0y^1_0\in\cH_y^3=\mathrm{Span}\{b, A^2b\}$, and $\Gamma_y^0b = (\Gamma_y^0)^\top b = b.$ That is 
\begin{equation}
\label{thm:gen-prox-1}
x_0^1\in U_1^\top\cH_x^3,\qquad\mbox{and}\qquad y_0^1\in V_1^\top\cH_y^3, \quad V_1 b = V_1^\top b = b,
\end{equation}	
where $U_1 = U_0\Gamma_x^0$ and $V_1 = V_0\Gamma_y^0$.


	Now we prove that when we apply the algorithm $\cA$ to $F_{U_1,V_1}$, the generated iterates $\{(x^0_1, y^0_1), (x^1_1, y^1_1)\}$ satisfy that
	$(x^0_1, y^0_1) = (0, 0)$ and  $(x^1_1, y^1_1) = (x^1_0, y^1_0)$. That is, the first two iterates generated by $\cA$ is completely the same for $F_{U_0,V_0}$ and $F_{U_1,V_1}$. The reason is because 
	$u^1_1 = \cA_u^1(\theta; x^0_1, U_1^\top AV_1y^0_1) = \cA_u^1(\theta; 0, 0) = \cA_u^1(\theta; x^0_0, U_0^\top AV_0y^0_0)  = u^1_0$, 
	therefore 
	\begin{eqnarray*}
		(x^1_1, \tilde x^1_1) & = & \cA_x^1(\theta; x^0_1, U_1^\top A V_1 y_1^0, \mathbf{prox}_{\gamma_1f}(u^1_1)) \\
		& = & \cA_x^1(\theta; 0, 0, \mathbf{prox}_{\gamma_1f}(u^1_1)) \\
		& = & \cA_x^1(\theta; x^0_0, U_0^\top A V_0 y_0^0, \mathbf{prox}_{\gamma_1f}(u^1_0)) \\
		& = & (x^1_0, \tilde x^1_0).
	\end{eqnarray*}
	Through similar argument, we know $(y^1_1,\tilde y^1_1) = (y^1_0,\tilde y^1_0)$. Therefore, \eqref{thm:gen-prox-1} indicates that 
	\begin{equation}
	\label{thm:gen-prox-2}
	x_1^1\in U_1^\top\cH_x^3,\qquad\mbox{and}\qquad y_1^1\in V_1^\top\cH_y^3, \quad V_1 b = V_1^\top b = b\in V_1^\top\cH_y^3.
	\end{equation}

Note that  $x_1^1 \in U_1^\top\cH_x^3 \subsetneqq U_1^\top\cH_x^5\subsetneqq U_1^\top\cH_x^7$ and $\{y_1^1,b\}\subsetneqq V_1^\top\cH_y^3\subsetneqq V_1^\top\cH_y^5\subsetneqq V_1^\top\cH_y^7$. Therefore, there exist orthogonal matrices $\Gamma_x^1$ and $\Gamma_y^1$ such that 
\begin{equation}
\label{thm:gen-prox-3}
\begin{cases}
\Gamma_x^1x = (\Gamma_x^1)^\top x = x, \,\,\forall x\in U_1^\top\cH_x^5,\,\,\,\, \Gamma_x^1 x_1^2\in U_1^\top\cH_x^7,\\
\Gamma_y^1y \,= (\Gamma_y^1)^\top y = y, \,\,\,\forall y\in V_1^\top\cH_y^5,\,\,\,\, \Gamma_y^1 y_1^2\in V_1^\top\cH_y^7.
\end{cases}
\end{equation}
Now, let us define 
$$U_2 = U_1\Gamma_x^1\qquad\mbox{and}\qquad V_2 = V_1\Gamma_y^1.$$

Through a similar argument, we have $(y_2^2,\tilde y_2^2) = (y_1^2,\tilde y_1^2)$. By \eqref{thm:gen-prox-2} and \eqref{thm:gen-prox-3}, we have 
\begin{equation}
\label{thm:gen-prox-4}
\{x_2^0,x_2^1,x_2^2\}\in U_2^\top\cH_x^7\qquad\mbox{and}\qquad\{b,y_2^0,y_2^1,y_2^2\}\in V_2^\top\cH_y^7.
\end{equation}

\textbf{Case $k$.} Suppose we already have orthogonal matrices $U_{k-1}, V_{k-1}$, such that when $\cA$ is applied to $F_{U_{k-1},V_{k-1}}$, we have
\begin{equation}
\label{thm:gen-prox-5}
\{x_{k-1}^0,x_{k-1}^1,\cdots, x_{k-1}^{k-1}\}\in U_{k-1}^\top\cH_x^{4k-5}\qquad\mbox{and}\qquad\{b,y_{k-1}^0,y_{k-1}^1,\cdots,y_{k-1}^{k-1}\}\in V_{k-1}^\top\cH_y^{4k-5}.
\end{equation}

Again, by Lemma \ref{lemma:yyx}, there exist orthogonal matrices $\Gamma_x^{k-1}$ and $\Gamma_y^{k-1}$, such that 
\begin{equation}
\label{thm:gen-prox-6}
\begin{cases}
\Gamma_x^{k-1}x = (\Gamma_x^{k-1})^\top x = x, \,\,\forall x\in U_{k-1}^\top\cH_x^{4k-3},\,\,\,\, \Gamma_x^{k-1} x_{k-1}^{k}\in U_{k-1}^\top\cH_x^{4k-1},\\
\Gamma_y^{k-1}y \,= (\Gamma_y^{k-1})^\top y = y, \,\,\,\forall y\in V_{k-1}^\top\cH_y^{4k-3},\,\,\,\, \Gamma_y^{k-1} y_{k-1}^k\in V_{k-1}^\top\cH_y^{4k-1}.
\end{cases}
\end{equation}
Now we define that 
$$U_k = U_{k-1}\Gamma_x^{k-1} \qquad\mbox{and}\qquad V_k = V_{k-1}\Gamma_y^{k-1}.$$

	Therefore, similar to our previous discussion, we only need to argue that when $\cA$ is applied to $F_{U_k,V_k}$, the generated iterates $\{(x_k^0,y_k^0), (x_k^1,y_k^1),\cdots,(x_k^k,y_k^k)\}$ satisfy $(x_k^i,y_k^i) = (x_{k-1}^i,y_{k-1}^i)$ for $i = 0,1,...,k$. We prove this argument by induction. First, it is straightforward that $(x_k^0,y_k^0) = (0,0) = (x_{k-1}^0,y_{k-1}^0)$. Suppose $(x_k^i,y_k^i) = (x_{k-1}^i,y_{k-1}^i)$ holds for $i = 0,1,...,j-1\leq k-1$, now we prove $(x_k^j,y_k^j) = (x_{k-1}^j,y_{k-1}^j)$, which is almost identical to the case $k=2$.

For any $i\in\{0,1,...,j-1\}$, let us show $U_{k-1}^\top AV_{k-1} y_{k-1}^i = U_k^\top AV_k y_k^i$. Because $y_k^i = y_{k-1}^i\in V_{k-1}^\top\cH_y^{4k-5}\subsetneqq V_{k-1}^\top\cH_y^{4k-3}$, we have $\Gamma_y^{k-1} y_k^i = y_k^i = y_{k-1}^i\in V_{k-1}^\top\cH_y^{4k-5}.$ Then $V_ky_k^i = V_{k-1}\Gamma_y^{k-1}y_k^i\in V_{k-1}V_{k-1}^\top\cH_y^{4k-5} = \cH_y^{4k-5}.$ Therefore $U_{k-1}^\top AV_{k}y_k^i\in U_{k-1}^\top A\cH_y^{4k-5} = U_{k-1}^\top\cH_x^{4k-3}$ and 
	$$U_k^\top AV_ky_k^i = (\Gamma_x^{k-1})^\top U_{k-1}^\top AV_ky_k^i = U_{k-1}^\top AV_{k}y_k^i = U_{k-1}^\top AV_{k-1}\Gamma_y^{k-1}y_k^i = U_{k-1}^\top AV_{k-1}y_{k-1}^i,$$ 
	for $0\leq i\leq j-1$. Consequently, 
	\begin{eqnarray*}
		u_k^i  & = & \cA_u^i(\theta; x_k^0, U_k^\top AV_k y_k^0,..., x_k^{i-1}, U_k^\top AV_k y_k^{i-1})\\
		& = & \cA_u^i(\theta; x_{k-1}^0, U_{k-1}^\top AV_{k-1} y_{k-1}^0,..., x_{k-1}^{i-1}, U_{k-1}^\top AV_{k-1} y_{k-1}^{i-1})\\
		& = & u_{k-1}^i
	\end{eqnarray*}
	and 
	\begin{eqnarray*}
		(x_k^i,\tilde x_k^i)  & = & \cA_x^i(\theta; x_k^0, U_k^\top AV_k y_k^0,..., x_k^{i-1}, U_k^\top AV_k y_k^{i-1},\mathbf{prox}_{\gamma_if}(u^i_k))\\
		& = &\cA_x^2(\theta; x_{k-1}^0, U_{k-1}^\top AV_{k-1} y_{k-1}^0,..., x_{k-1}^{i-1}, U_{k-1}^\top AV_{k-1} y_{k-1}^{i-1},\mathbf{prox}_{\gamma_if}(u^i_{k-1}))\\
		& = & (x_{k-1}^i,\tilde x_{k-1}^i).
	\end{eqnarray*}

	Through a similar argument, we have $(y_k^i,\tilde y_k^i) = (y_{k-1}^i,\tilde y_{k-1}^i)$. By induction, we know $(y_k^i,\tilde y_k^i) = (y_{k-1}^i,\tilde y_{k-1}^i)$ for $i = 0,1,...,k$. Consequently, we have 
	\begin{equation}
	\label{thm:gen-prox-7}
	\{x_{k}^0,x_{k}^1,\cdots, x_{k}^{k}\}\in U_{k}^\top\cH_x^{4k-1}\qquad\mbox{and}\qquad\{b,y_{k}^0,y_{k}^1,\cdots,y_{k}^{k}\}\in V_{k}^\top\cH_y^{4k-1}.
	\end{equation}
    By setting $\hat U = U_k$ and $\hat V = V_k$, we prove the result for Part I.\vspace{0.5cm}\\

	\textbf{Part II. There exist orthogonal matrices $U$, $V$ such that when $\cA$ is applied to the rotated instance $F_{U,V}$, $\{(x^0,y^0),...,(x^k,y^k)\}\subseteq U^\top\cH_x^{4k-1}\times V^\top\cH_y^{4k-1},$ and $(\tilde{x}^k,\tilde{y}^k)\in U^\top\cH_x^{4k+1}\times V^\top\cH_y^{4k+1}$}.

Given the result of Part I, and let $\{(x_k^0, y_k^0),...,(x_k^k, y_k^k)\}$ and $(\tilde x_k^k, \tilde y_k^k)$ be generated by $\cA$ when applied to $F_{\hat U,\hat V} = F_{U_k,V_k}$. Therefore, by Lemma \ref{lemma:yyx}, there exist orthogonal matrices $P,Q$ such that 
\begin{equation}
\label{thm:gen-prox-8}
\begin{cases}
Px = P^\top x = x, \,\,\forall x\in U_{k}^\top\cH_x^{4k-1},\,\,\,\, P \tilde x_{k}^{k}\in U_{k}^\top\cH_x^{4k+1},\\
Qy \,=Q^\top y = y, \,\,\forall y\in V_{k}^\top\cH_y^{4k-1},\,\,\,\, Q\tilde y_{k}^k\in V_{k}^\top\cH_y^{4k+1}.
\end{cases}
\end{equation}
